<?php
require_once dirname(__DIR__).'/includes/bootstrap.php';require_module('expenses');$pageTitle='Expense List';$activeMenu='expense-list';
$where='';$params=[];if(role_name()==='Staff'){$where='WHERE e.requested_by=?';$params[]=(int)current_user()['id'];}
$s=db()->prepare("SELECT e.*,d.name department,c.name category,CONCAT(u.first_name,' ',u.last_name) requester,(SELECT COUNT(*) FROM expense_receipts er WHERE er.expense_id=e.id) receipt_count FROM expenses e JOIN departments d ON d.id=e.department_id JOIN budget_categories c ON c.id=e.category_id JOIN users u ON u.id=e.requested_by $where ORDER BY e.id DESC");$s->execute($params);$rows=$s->fetchAll();
require ROOT_PATH.'/includes/header.php';?>
<div class="page-head"><div><h1>Expense Monitoring</h1><p>Track expenditure requests, supporting receipts, approval status and actual spend.</p></div><a href="<?=e(url('expenses/create.php'))?>" class="btn btn-primary"><i class="fa-solid fa-plus me-2"></i>New Expense Request</a></div>
<div class="card-panel"><div class="card-head"><h2 class="section-title">Expense Register</h2><a class="small text-decoration-none" href="<?=e(url('expenses/upload.php'))?>"><i class="fa-solid fa-paperclip me-1"></i>Upload receipt</a></div><div class="card-body"><div class="table-responsive"><table class="table data-table"><thead><tr><th>Code</th><th>Date</th><th>Department</th><th>Category</th><th>Description</th><th class="text-end">Amount</th><th>Receipts</th><th>Requested By</th><th>Status</th><th class="no-print">Actions</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td class="fw-bold text-primary"><?=e($r['expense_code'])?></td><td><?=e(date('M d, Y',strtotime($r['expense_date'])))?></td><td><?=e($r['department'])?></td><td><?=e($r['category'])?></td><td><?=e($r['description'])?></td><td class="text-end fw-semibold"><?=money($r['amount'])?></td><td><span class="badge bg-light text-dark border"><?=(int)$r['receipt_count']?> file(s)</span></td><td><?=e($r['requester'])?></td><td><?=status_badge($r['status'])?></td><td class="no-print"><div class="table-actions"><?php if($r['status']!=='Approved'||is_admin()):?><a class="btn btn-light border" href="<?=e(url('expenses/edit.php?id='.$r['id']))?>"><i class="fa-solid fa-pen"></i></a><?php endif;?><a class="btn btn-light border" href="<?=e(url('expenses/upload.php?expense_id='.$r['id']))?>"><i class="fa-solid fa-paperclip"></i></a><?php if(is_admin() || (role_name()==='Finance Manager' && $r['status']!=='Approved')):?><a class="btn btn-light border text-danger" data-confirm="Delete this expense record and its approval request?" href="<?=e(url('expenses/delete.php?id='.$r['id'].'&token='.csrf_token()))?>"><i class="fa-solid fa-trash"></i></a><?php endif;?></div></td></tr><?php endforeach;?></tbody></table></div></div></div>
<?php require ROOT_PATH.'/includes/footer.php';?>
